public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Request body must not be null or blank');
        }

        Object deserialized;
        try {
            deserialized = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON: ' + e.getMessage());
        }

        if (deserialized == null || !(deserialized instanceof Map)) {
            throw new PayloadException('JSON root must be an object');
        }

        Map root = (Map) deserialized;

        String orderNum = getString(root, 'number');
        if (orderNum == null || String.isBlank(orderNum)) {
            throw new PayloadException('Field "number" is missing or blank');
        }

        Date orderDate = null;
        Object dateVal = root.get('date');
        if (dateVal instanceof String) {
            try {
                orderDate = Date.parse((String) dateVal);
            } catch (Exception e) {
                throw new PayloadException('Field "date" is not a valid ISO date');
            }
        }

        String currencyCode = getString(root, 'currency');

        String customerEmail = null;
        Object custVal = root.get('customer');
        if (custVal instanceof Map) {
            Map custMap = (Map) custVal;
            customerEmail = getString(custMap, 'email');
        }

        List<Line> lines = new List<Line>();
        Object linesVal = root.get('lines');
        if (linesVal instanceof List) {
            List linesList = (List) linesVal;
            for (Object item : linesList) {
                if (!(item instanceof Map)) {
                    throw new PayloadException('Each element in "lines" must be a JSON object');
                }
                Map lineMap = (Map) item;
                lines.add(parseLine(lineMap));
            }
        }

        Decimal total = 0;
        for (Line ln : lines) {
            total += ln.lineTotal;
        }

        Order order = new Order();
        order.orderNumber = orderNum;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;
        return order;
    }

    private static Line parseLine(Map lineMap) {
        String sku = getString(lineMap, 'sku');
        if (sku == null) {
            throw new PayloadException('Line is missing required field "sku"');
        }

        Integer quantity = null;
        Object qtyVal = lineMap.get('quantity');
        if (qtyVal instanceof Decimal) {
            Decimal d = (Decimal) qtyVal;
            if (d == d.intValue()) {
                quantity = d.intValue();
            }
        }
        if (quantity == null || quantity <= 0) {
            throw new PayloadException('Line has missing or non-positive "quantity"');
        }

        Decimal unitPrice = null;
        Object priceVal = lineMap.get('unitPrice');
        if (priceVal instanceof Decimal) {
            unitPrice = (Decimal) priceVal;
        }
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Line has missing or negative "unitPrice"');
        }

        Decimal discount = 0;
        Object discVal = lineMap.get('discount');
        if (discVal instanceof Decimal) {
            discount = (Decimal) discVal;
        }

        Decimal raw = quantity * unitPrice * (1 - discount);
        Decimal lineTotal = roundHalfUp2(raw);

        Line line = new Line();
        line.sku = sku;
        line.quantity = quantity;
        line.unitPrice = unitPrice;
        line.discount = discount;
        line.lineTotal = lineTotal;
        return line;
    }

    private static Decimal roundHalfUp2(Decimal value) {
        if (value == null) {
            return 0;
        }
        return Math.round(value * 100) / 100;
    }

    private static String getString(Map source, String fieldName) {
        Object val = source.get(fieldName);
        if (val instanceof String) {
            return (String) val;
        }
        return null;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
