@IsTest
private class OpportunityWonHandlerTest {

    private static User testUser;

    @TestSetup
    static void setup() {
        Profile admProfile = [SELECT Id FROM Profile WHERE Name = 'System Administrator' LIMIT 1];
        testUser = new User(
            Username = 'oppwon_test_' + DateTime.now().getTime() + '@test.com',
            Email = 'oppwon_test@test.com',
            LastName = 'OppWon',
            Alias = 'owtst',
            ProfileId = admProfile.Id
        );
        insert testUser;
    }

    private static Opportunity newOpp(String name, String stage, Id accountId, Id ownerId, Date closeDate) {
        return new Opportunity(
            Name = name,
            StageName = stage,
            AccountId = accountId,
            OwnerId = ownerId,
            CloseDate = closeDate,
            TimeZoneSidKey = 'America/Chicago',
            LocaleSidKey = 'en_US',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US'
        );
    }

    // ─── INSERT: newly won ────────────────────────────────────────────────────

    @IsTest
    static void insert_closedWon_nextStep_task_accountHot() {
        Account acc = new Account(Name = 'Insert Acct', Rating = 'Warm');
        insert acc;

        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpp('Insert Won Opp', 'Closed Won', acc.Id, testUser.Id, closeDate);

        Test.startTest();
        insert opp;
        Test.stopTest();

        // NextStep set in before-insert
        Opportunity reOpp = [SELECT Id, NextStep, StageName FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Handover to Customer Success', reOpp.NextStep,
            'NextStep should be set on newly won insert');

        // Task created in after-insert
        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
                            FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task should be created');
        Task t = tasks[0];
        System.assertEquals('Customer kick-off', t.Subject);
        System.assertEquals(opp.OwnerId, t.OwnerId);
        System.assertEquals(closeDate.addDays(7), t.ActivityDate,
            'ActivityDate must be CloseDate + 7');
        System.assertEquals('High', t.Priority);

        // Account rated Hot
        System.assertEquals('Hot', [SELECT Rating FROM Account WHERE Id = :acc.Id].Rating);
    }

    @IsTest
    static void insert_closedWon_noAccount() {
        Date closeDate = Date.newInstance(2025, 3, 10);
        Opportunity opp = newOpp('No Account Won', 'Closed Won', null, testUser.Id, closeDate);

        Test.startTest();
        insert opp;
        Test.stopTest();

        System.assertEquals('Handover to Customer Success',
            [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id].NextStep);

        List<Task> tasks = [SELECT Subject, ActivityDate, Priority FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size());
        System.assertEquals('Customer kick-off', tasks[0].Subject);
        System.assertEquals(closeDate.addDays(7), tasks[0].ActivityDate);
        System.assertEquals('High', tasks[0].Priority);
    }

    @IsTest
    static void insert_closedWon_accountAlreadyHot() {
        Account acc = new Account(Name = 'Already Hot', Rating = 'Hot');
        insert acc;

        Opportunity opp = newOpp('Opp to Hot Acct', 'Closed Won', acc.Id, testUser.Id,
            Date.today().addDays(20));

        Test.startTest();
        insert opp;
        Test.stopTest();

        // Account stays Hot, no error
        System.assertEquals('Hot', [SELECT Rating FROM Account WHERE Id = :acc.Id].Rating);
        // Task still created
        System.assertEquals(1, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id]);
    }

    // ─── INSERT: not won → no side effects ───────────────────────────────────

    @IsTest
    static void insert_notWon_noChanges() {
        Account acc = new Account(Name = 'NonWon Acct', Rating = 'Warm');
        insert acc;

        Opportunity opp = newOpp('Open Opp', 'Prospecting', acc.Id, testUser.Id,
            Date.today().addDays(60));

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity reOpp = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(null, reOpp.NextStep, 'NextStep must not be set on non-won insert');
        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id]);
        System.assertEquals('Warm', [SELECT Rating FROM Account WHERE Id = :acc.Id].Rating);
    }

    // ─── UPDATE: to Closed Won ────────────────────────────────────────────────

    @IsTest
    static void update_toClosedWon_handoverFires() {
        Account acc = new Account(Name = 'Update Acct', Rating = 'Cold');
        insert acc;

        Date closeDate = Date.today().addDays(14);
        Opportunity opp = newOpp('Was Prospecting', 'Prospecting', acc.Id, testUser.Id, closeDate);
        insert opp;

        Test.startTest();
        opp.StageName = 'Closed Won';
        update opp;
        Test.stopTest();

        Opportunity reOpp = [SELECT NextStep, StageName FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Closed Won', reOpp.StageName);
        System.assertEquals('Handover to Customer Success', reOpp.NextStep);

