public with sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (objectApiName == null || fieldApiName == null
            || objectApiName.trim() == '' || fieldApiName.trim() == '') {
            throw new PicklistServiceException(
                'Object and field API names must not be null or blank.');
        }

        Schema.SObjectField sobjField = resolveField(objectApiName, fieldApiName);
        Schema.DescribeFieldResult fldDescribe = sobjField.getDescribe();

        if (fldDescribe.getType() != Schema.DisplayType.PICKLIST
            && fldDescribe.getType() != Schema.DisplayType.COMBOBOX) {
            throw new PicklistServiceException(
                'Field [' + fieldApiName + '] is not a picklist or multi-select picklist; actual type: '
                + fldDescribe.getType());
        }

        String defaultValue = (String)fldDescribe.getDefaultValue();

        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry pe : fldDescribe.getPicklistValues()) {
            if (!pe.isActive()) {
                continue;
            }
            Option opt = new Option();
            opt.value = pe.getValue();
            opt.label = pe.getLabel();
            opt.isDefault = defaultValue != null && pe.getValue() == defaultValue;
            options.add(opt);
        }
        return options;
    }

    private static Schema.SObjectField resolveField(String objectApiName, String fieldApiName) {
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        String objTarget = objectApiName.toLowerCase();
        Schema.SObjectType sobjType = null;
        for (String key : globalMap.keySet()) {
            if (key.toLowerCase() == objTarget) {
                sobjType = globalMap.get(key);
                break;
            }
        }
        if (sobjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = sobjType.getDescribe();
        Schema.SObjectTypeFields fieldMap = objDescribe.fields;
        String fldTarget = fieldApiName.toLowerCase();
        for (String key : fieldMap.keySet()) {
            if (key.toLowerCase() == fldTarget) {
                return fieldMap.get(key);
            }
        }
        throw new PicklistServiceException(
            'Field does not exist on object: ' + fieldApiName);
    }
}
