public without sharing class OpportunityPipelineHandler {

    /**
     * Recursion guard: updating Accounts fires the legacy AccountTrigger,
     * which updates open Opportunities, which would re-enter our trigger.
     * This flag breaks that loop.
     */
    private static Boolean isRecalculating = false;

    /**
     * Recalculates FB_Open_Pipeline__c and FB_Open_Opportunities__c for the
     * given Account Ids by querying all currently-open opportunities on those
     * accounts and computing sums and counts from scratch.
     *
     * This is idempotent and correct regardless of how the open set changed
     * (insert, amount edit, stage flip, account move, delete, undelete) and
     * regardless of how many DML statements occurred earlier in the same
     * transaction, because each invocation reads the current database state.
     *
     * Bulk-safe: one SOQL and one DML per call, well within governor limits
     * for 200 opportunities.
     */
    public static void recalculate(Set<Id> accountIds) {
        if (isRecalculating) {
            return;
        }

        isRecalculating = true;
        try {
            // Pre-seed with zeros so accounts whose last open opp disappeared
            // get 0 and 0 rather than null.
            Map<Id, Decimal> pipelineMap = new Map<Id, Decimal>();
            Map<Id, Integer> countMap = new Map<Id, Integer>();
            for (Id accId : accountIds) {
                pipelineMap.put(accId, 0);
                countMap.put(accId, 0);
            }

            // Query all open opportunities for the affected accounts.
            List<Opportunity> openOpps = [
                SELECT Id, AccountId, Amount
                FROM Opportunity
                WHERE AccountId IN :accountIds
                AND IsClosed = false
            ];

            for (Opportunity opp : openOpps) {
                Decimal amt = opp.Amount != null ? opp.Amount : 0;
                pipelineMap.put(opp.AccountId, pipelineMap.get(opp.AccountId) + amt);
                countMap.put(opp.AccountId, countMap.get(opp.AccountId) + 1);
            }

            // Build the update list (no size hint — Apex pre-fills with nulls).
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                Account acc = new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = pipelineMap.get(accId),
                    FB_Open_Opportunities__c = countMap.get(accId)
                );
                accountsToUpdate.add(acc);
            }

            update accountsToUpdate;
        } finally {
            isRecalculating = false;
        }
    }
}
