public class Opportunities extends fflib_SObjectDomain {

    private final Set<Id> m_qualifyingOpportunityIds = new Set<Id>();

    public class Constructor implements fflib_SObjectDomain.IConstructable {

        private final String m_eventName;
        private final Map<Id, SObject> m_sObjectMap;
        private final Map<Id, SObject> m_oldSObjectMap;

        public Constructor(
            List<SObject> newRecords,
            List<SObject> oldRecords,
            Boolean isInsert,
            Boolean isUpdate,
            Boolean isDelete,
            Boolean isAfter
        ) {
            m_sObjectMap = new Map<Id, SObject>();
            for (SObject sObj : newRecords) {
                m_sObjectMap.put(sObj.Id, sObj);
            }
            m_oldSObjectMap = new Map<Id, SObject>();
            for (SObject sObj : oldRecords) {
                m_oldSObjectMap.put(sObj.Id, sObj);
            }
            if (isAfter) {
                if (isInsert) {
                    m_eventName = 'afterInsert';
                } else if (isUpdate) {
                    m_eventName = 'afterUpdate';
                } else if (isDelete) {
                    m_eventName = 'afterDelete';
                } else {
                    m_eventName = 'afterUndelete';
                }
            } else {
                if (isInsert) {
                    m_eventName = 'beforeInsert';
                } else if (isUpdate) {
                    m_eventName = 'beforeUpdate';
                } else if (isDelete) {
                    m_eventName = 'beforeDelete';
                } else {
                    m_eventName = 'beforeUndelete';
                }
            }
        }

        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities(m_eventName, m_sObjectMap, m_oldSObjectMap);
        }
    }

    public Opportunities(
        String eventName,
        Map<Id, SObject> sObjectMap,
        Map<Id, SObject> oldSObjectMap
    ) {
        super(eventName, sObjectMap, oldSObjectMap);
    }

    public override void handle() {
        if (this.getEventName() == 'afterInsert') {
            for (Id id : this.getSObjectMap().keySet()) {
                Opportunity opp = (Opportunity) this.getSObjectMap().get(id);
                if (opp.StageName == 'Closed Won') {
                    m_qualifyingOpportunityIds.add(id);
                }
            }
            commitFulfilment();
        } else if (this.getEventName() == 'afterUpdate') {
            for (Id id : this.getSObjectMap().keySet()) {
                Opportunity opp = (Opportunity) this.getSObjectMap().get(id);
                Opportunity oldOpp = (Opportunity) this.getOldSObjectMap().get(id);
                if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                    m_qualifyingOpportunityIds.add(id);
                }
            }
            commitFulfilment();
        }
    }

    private void commitFulfilment() {
        if (!m_qualifyingOpportunityIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(m_qualifyingOpportunityIds);
        }
    }
}
