    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> accountFields = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            accountFields.add(field.getDescribe().getName());
        }

        ContactsSelector cs = new ContactsSelector();
        List<String> contactFields = new List<String>();
        for (Schema.SObjectField field : cs.getSObjectFieldList()) {
            contactFields.add(field.getDescribe().getName());
        }

        String soql = 'SELECT ' + String.join(accountFields, ', ')
                   + ' FROM Account WHERE Id IN :accountIds'
                   + ' (SELECT ' + String.join(contactFields, ', ')
                   + ' FROM Contacts)';

        String da = this.getDataAccess();
        if (da == 'SYSTEM_MODE') {
            soql += ' WITH SYSTEM_MODE';
        } else {
            soql += ' WITH USER_MODE';
        }

        return (List<Account>) Database.query(soql);
    }
}
