        List<Account> accounts = new List<Account>();
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acc = new Account(Name = accountName);
            accounts.add(acc);
            uow.addSObject(acc);
        }
        uow.commitWork();

        // Phase 2 – queue all Contacts referencing the now-persisted Account Ids, then commit
        for (Account acc : accounts) {
            List<String> lastNames = contactLastNamesByAccountName.get(acc.Name);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName, AccountId = acc.Id);
                    uow.addSObject(con);
                }
            }
        }
        uow.commitWork();

