trigger CaseTrigger on Case (after update) {
    if (Trigger.isAfter && Trigger.isUpdate) {
        List<Id> eligibleCaseIds = new List<Id>();

        for (Case c : Trigger.new) {
            Case oldC = Trigger.oldMap.get(c.Id);
            // Transition: was open, now closed, and has a contact
            if (c.IsClosed && !oldC.IsClosed && c.ContactId != null) {
                eligibleCaseIds.add(c.Id);
            }
        }

        if (!eligibleCaseIds.isEmpty()) {
            // Governor limit: 50 System.enqueueJob calls per transaction.
            // Chunk into batches of 50 so 200 cases = 4 enqueues (well within limit).
            Integer batchSize = 50;
            for (Integer i = 0; i < eligibleCaseIds.size(); i += batchSize) {
                Integer endIndex = Math.min(i + batchSize, eligibleCaseIds.size());
                List<Id> batch = new List<Id>();
                for (Integer j = i; j < endIndex; j++) {
                    batch.add(eligibleCaseIds[j]);
                }
                System.enqueueJob(new CaseSurveyJob(batch));
            }
        }
    }
}
