```html
<template>
    <button
        type="button"
        class="slds-button slds-button_icon"
        aria-pressed={favorite}
        aria-label={actionLabel}
        title={actionLabel}
        onclick={handleClick}>
        <lightning-icon icon-name="custom:custom14" alternative-text="" size="small"></lightning-icon>
    </button>
