import { LightningElement, wire } from 'lwc';
import { subscribe, unsubscribe, publish, MessageContext } from 'lightning/messageService';
import Account_Selected from '@salesforce/messageChannel/Account_Selected__c';

const APPLICATION_SCOPE = 'APPLICATION_SCOPE';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext) messageContext;

    selectedRecordId;
    _messageSubscription;

    get hasNoRecord() {
        return !this.selectedRecordId;
    }

    connectedCallback() {
        if (!this._messageSubscription) {
            this._messageSubscription = subscribe(
                this.messageContext,
                Account_Selected,
                (message) => this.handleMessage(message),
                APPLICATION_SCOPE
            );
        }
    }

    disconnectedCallback() {
        if (this._messageSubscription) {
            unsubscribe(this._messageSubscription);
            this._messageSubscription = null;
        }
    }

    handleMessage(message) {
        this.selectedRecordId = message.recordId || null;
    }

    handleClear() {
        publish(
            this.messageContext,
            Account_Selected,
            { recordId: null },
            APPLICATION_SCOPE
        );
    }
}
