public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = new List<Contact>();
        for (SObject so : triggerNew) {
            contacts.add((Contact) so);
        }
        process(contacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = new List<Contact>();
        List<Contact> oldContacts = new List<Contact>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            newContacts.add((Contact) triggerNew[i]);
            oldContacts.add((Contact) triggerOld[i]);
        }
        process(newContacts, oldContacts);
    }

    private void process(List<Contact> contacts, List<Contact> oldContacts) {
        if (contacts.isEmpty()) {
            return;
        }

        // Step 1: filter to contacts that need checking
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> selfIds = new Set<Id>();

        for (Integer i = 0; i < contacts.size(); i++) {
            Contact c = contacts[i];

            // Skip contacts without an Account or without an Email
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            // On update, skip contacts whose Email and AccountId did not change
            if (oldContacts != null) {
                Contact old = oldContacts[i];
                if (c.Email == old.Email && c.AccountId == old.AccountId) {
                    continue;
                }
                selfIds.add(c.Id);
            }

            toCheck.add(c);
            accountIds.add(c.AccountId);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // Step 2: single SOQL – fetch existing contacts on the relevant accounts
        Map<String, Boolean> existingKeys = new Map<String, Boolean>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            // Exclude self so a record does not conflict with its own prior state
            if (selfIds.contains(c.Id)) {
                continue;
            }
            existingKeys.put(buildKey(c.AccountId, c.Email), true);
        }

        // Step 3: walk the batch in order; first occurrence wins, later ones are rejected
        Set<String> takenKeys = new Set<String>(existingKeys.keySet());

        for (Contact c : toCheck) {
            String key = buildKey(c.AccountId, c.Email);
            if (takenKeys.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                takenKeys.add(key);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        return accountId + '|' + email.toLowerCase();
    }
}
