            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            if (isBlank(c.LeadSource)) {
                c.LeadSource = acc.AccountSource;
            }
        }
    }

    private static Boolean isBlank(String val) {
        return val == null || val.trim() == '';
    }
}
